using Microsoft.Data.Sqlite;
using Pharma.Dal;
using Pharma.Models;

namespace Pharma.Bll;

public sealed class GestionOperationsStockService
{
    private readonly string _cs; private readonly ActionLogRepository _logs;
    public GestionOperationsStockService(string connectionString){_cs=connectionString;_logs=new ActionLogRepository(connectionString);}
    public long ValiderReception(Reception reception,IReadOnlyList<(long ProduitId,string NumeroLot,DateTime Peremption,int Quantite,decimal CoutAchat)> lignes,Utilisateur auteur)
    { ExigerAdmin(auteur);if(lignes.Count==0)throw new InvalidOperationException("La réception est vide.");using var c=new SqliteConnection(_cs);c.Open();using var tx=c.BeginTransaction();using var h=c.CreateCommand();h.Transaction=tx;h.CommandText="INSERT INTO Receptions(DateReception,FournisseurId,ReferenceDocument,UtilisateurId,Statut) VALUES($date,$fournisseur,$ref,$user,'Validee');SELECT last_insert_rowid()";h.Parameters.AddWithValue("$date",reception.DateReception.ToString("O"));h.Parameters.AddWithValue("$fournisseur",(object?)reception.FournisseurId??DBNull.Value);h.Parameters.AddWithValue("$ref",(object?)reception.ReferenceDocument??DBNull.Value);h.Parameters.AddWithValue("$user",auteur.Id);var id=Convert.ToInt64(h.ExecuteScalar());foreach(var l in lignes){if(l.ProduitId<=0||l.Quantite<=0||l.CoutAchat<0||string.IsNullOrWhiteSpace(l.NumeroLot))throw new ArgumentException("Ligne de réception invalide.");using var lot=c.CreateCommand();lot.Transaction=tx;lot.CommandText="SELECT Id FROM Lots WHERE ProduitId=$p AND NumeroLot=$lot";lot.Parameters.AddWithValue("$p",l.ProduitId);lot.Parameters.AddWithValue("$lot",l.NumeroLot.Trim());var existing=lot.ExecuteScalar();long lotId;if(existing is null){using var ins=c.CreateCommand();ins.Transaction=tx;ins.CommandText="INSERT INTO Lots(ProduitId,NumeroLot,DatePeremption,QuantitePhysique,QuantiteVendable,CoutAchat,IsBloque) VALUES($p,$lot,$date,$q,$q,$cout,0);SELECT last_insert_rowid()";ins.Parameters.AddWithValue("$p",l.ProduitId);ins.Parameters.AddWithValue("$lot",l.NumeroLot.Trim());ins.Parameters.AddWithValue("$date",l.Peremption.ToString("yyyy-MM-dd"));ins.Parameters.AddWithValue("$q",l.Quantite);ins.Parameters.AddWithValue("$cout",l.CoutAchat);lotId=Convert.ToInt64(ins.ExecuteScalar());}else{lotId=Convert.ToInt64(existing);using var up=c.CreateCommand();up.Transaction=tx;up.CommandText="UPDATE Lots SET QuantitePhysique=QuantitePhysique+$q,QuantiteVendable=QuantiteVendable+$q,DatePeremption=$date,CoutAchat=$cout WHERE Id=$id AND IsBloque=0";up.Parameters.AddWithValue("$q",l.Quantite);up.Parameters.AddWithValue("$date",l.Peremption.ToString("yyyy-MM-dd"));up.Parameters.AddWithValue("$cout",l.CoutAchat);up.Parameters.AddWithValue("$id",lotId);if(up.ExecuteNonQuery()!=1)throw new InvalidOperationException("Le lot est bloqué.");}using var line=c.CreateCommand();line.Transaction=tx;line.CommandText="INSERT INTO LignesReception(ReceptionId,ProduitId,LotId,Quantite,CoutAchat) VALUES($r,$p,$l,$q,$cout)";line.Parameters.AddWithValue("$r",id);line.Parameters.AddWithValue("$p",l.ProduitId);line.Parameters.AddWithValue("$l",lotId);line.Parameters.AddWithValue("$q",l.Quantite);line.Parameters.AddWithValue("$cout",l.CoutAchat);line.ExecuteNonQuery();Mouvement(c,tx,lotId,l.Quantite,"Reassort",auteur.Id);} _logs.Enregistrer(auteur.Id,$"Réception {id} validée",c,tx);tx.Commit();return id; }
    public void AjusterStock(long lotId,int nouvelleQuantite,string motif,Utilisateur auteur){ExigerAdmin(auteur);if(nouvelleQuantite<0||string.IsNullOrWhiteSpace(motif))throw new ArgumentException("Correction de stock invalide.");using var c=new SqliteConnection(_cs);c.Open();using var tx=c.BeginTransaction();using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT QuantitePhysique FROM Lots WHERE Id=$id";q.Parameters.AddWithValue("$id",lotId);var actuel=q.ExecuteScalar();if(actuel is null)throw new KeyNotFoundException("Lot introuvable.");var ancien=Convert.ToInt32(actuel);var delta=nouvelleQuantite-ancien;if(delta==0){tx.Rollback();return;}using var up=c.CreateCommand();up.Transaction=tx;up.CommandText="UPDATE Lots SET QuantitePhysique=$q,QuantiteVendable=MAX(0,MIN(QuantiteVendable+$delta,$q)) WHERE Id=$id";up.Parameters.AddWithValue("$q",nouvelleQuantite);up.Parameters.AddWithValue("$delta",delta);up.Parameters.AddWithValue("$id",lotId);up.ExecuteNonQuery();Mouvement(c,tx,lotId,delta,delta<0?"Perte":"Reassort",auteur.Id);_logs.Enregistrer(auteur.Id,$"Correction du lot {lotId}: {ancien} vers {nouvelleQuantite}. Motif: {motif.Trim()}",c,tx);tx.Commit();}
    public void RetournerVente(long venteId,string motif,Utilisateur auteur){ExigerAdmin(auteur);if(string.IsNullOrWhiteSpace(motif))throw new ArgumentException("Le motif est obligatoire.");using var c=new SqliteConnection(_cs);c.Open();using var tx=c.BeginTransaction();using var status=c.CreateCommand();status.Transaction=tx;status.CommandText="SELECT Statut FROM Ventes WHERE Id=$id";status.Parameters.AddWithValue("$id",venteId);var statut=status.ExecuteScalar()?.ToString();if(statut is null||statut=="Annulee")throw new InvalidOperationException("Vente introuvable ou déjà annulée.");using var lines=c.CreateCommand();lines.Transaction=tx;lines.CommandText="SELECT Id,LotId,Quantite,PrixVente FROM LignesVente WHERE VenteId=$id";lines.Parameters.AddWithValue("$id",venteId);using var r=lines.ExecuteReader();var rows=new List<(long,long,int,decimal)>();while(r.Read())rows.Add((r.GetInt64(0),r.GetInt64(1),r.GetInt32(2),r.GetDecimal(3)));r.Close();var total=rows.Sum(x=>x.Item3*x.Item4);using var ret=c.CreateCommand();ret.Transaction=tx;ret.CommandText="INSERT INTO RetoursVente(VenteId,DateRetour,UtilisateurId,Motif,Total) VALUES($v,$date,$user,$motif,$total);SELECT last_insert_rowid()";ret.Parameters.AddWithValue("$v",venteId);ret.Parameters.AddWithValue("$date",DateTime.Now.ToString("O"));ret.Parameters.AddWithValue("$user",auteur.Id);ret.Parameters.AddWithValue("$motif",motif.Trim());ret.Parameters.AddWithValue("$total",total);var rid=Convert.ToInt64(ret.ExecuteScalar());foreach(var row in rows){using var up=c.CreateCommand();up.Transaction=tx;up.CommandText="UPDATE Lots SET QuantitePhysique=QuantitePhysique+$q,QuantiteVendable=QuantiteVendable+$q WHERE Id=$id";up.Parameters.AddWithValue("$q",row.Item3);up.Parameters.AddWithValue("$id",row.Item2);up.ExecuteNonQuery();using var lr=c.CreateCommand();lr.Transaction=tx;lr.CommandText="INSERT INTO LignesRetourVente(RetourId,LigneVenteId,LotId,Quantite,Montant) VALUES($r,$l,$lot,$q,$m)";lr.Parameters.AddWithValue("$r",rid);lr.Parameters.AddWithValue("$l",row.Item1);lr.Parameters.AddWithValue("$lot",row.Item2);lr.Parameters.AddWithValue("$q",row.Item3);lr.Parameters.AddWithValue("$m",row.Item3*row.Item4);lr.ExecuteNonQuery();Mouvement(c,tx,row.Item2,row.Item3,"Retour",auteur.Id);}using var cancel=c.CreateCommand();cancel.Transaction=tx;cancel.CommandText="UPDATE Ventes SET Statut='Annulee' WHERE Id=$id";cancel.Parameters.AddWithValue("$id",venteId);cancel.ExecuteNonQuery();_logs.Enregistrer(auteur.Id,$"Annulation/retour de la vente {venteId}: {motif.Trim()}",c,tx);tx.Commit();}
    private static void Mouvement(SqliteConnection c,SqliteTransaction tx,long lotId,int q,string motif,long user){using var m=c.CreateCommand();m.Transaction=tx;m.CommandText="INSERT INTO MouvementsStock(DateMouvement,LotId,Quantite,Motif,UtilisateurId) VALUES($date,$lot,$q,$motif,$user)";m.Parameters.AddWithValue("$date",DateTime.Now.ToString("O"));m.Parameters.AddWithValue("$lot",lotId);m.Parameters.AddWithValue("$q",q);m.Parameters.AddWithValue("$motif",motif);m.Parameters.AddWithValue("$user",user);m.ExecuteNonQuery();}
    private static void ExigerAdmin(Utilisateur u){if(u.Role!=RoleUtilisateur.Administrateur)throw new UnauthorizedAccessException("Cette opération est réservée au responsable.");}
}
